{
  "name": "@capiro/meri-contracts",
  "version": "0.1.2",
  "private": true,
  "license": "UNLICENSED",
  "type": "module",
  "description": "Public distribution of frozen Meri wire shapes; validation grants no authorization",
  "files": [
    "meri.schema.json",
    "validate.mjs",
    "dist",
    "README.md",
    "THIRD-PARTY-NOTICES.md"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/browser.mjs"
    },
    "./browser": {
      "types": "./dist/browser.d.ts",
      "default": "./dist/browser.mjs"
    },
    "./node": "./validate.mjs",
    "./metadata": {
      "types": "./dist/metadata.d.ts",
      "default": "./dist/metadata.mjs"
    },
    "./schema": "./meri.schema.json",
    "./action-application": {
      "types": "./dist/action-application.d.ts",
      "default": "./dist/action-application.mjs"
    },
    "./action-application/schema": "./dist/action-application.schema.json",
    "./document-application": {
      "types": "./dist/document-application.d.ts",
      "default": "./dist/document-application.mjs"
    },
    "./document-application/schema": "./dist/document-application.schema.json"
  },
  "scripts": {
    "build": "node generate.mjs && node generate-actions.mjs && node generate-documents.mjs",
    "check:generated": "node generate.mjs --check && node generate-actions.mjs --check && node generate-documents.mjs --check",
    "typecheck": "tsc --noEmit --strict --skipLibCheck --target ES2022 --module NodeNext --moduleResolution NodeNext test/public-types.ts test/action-application-public-types.ts test/document-application-public-types.ts",
    "test:public": "node --test test/public-package.test.mjs test/action-application-public.test.mjs test/document-application-public.test.mjs",
    "check": "npm run check:generated && npm run typecheck && npm run test:public"
  },
  "dependencies": {
    "ajv": "8.20.0",
    "ajv-formats": "3.0.1",
    "canonicalize": "5.1.0"
  },
  "devDependencies": {
    "esbuild": "0.28.2",
    "json-schema-to-typescript": "16.0.0",
    "typescript": "5.9.3"
  },
  "engines": {
    "node": ">=24 <25"
  }
}
